            self._cmd = "dnf" if shutil.which("dnf") else "yum"
        return self._cmd

    def get_installed_packages(self) -> List[Dict[str, any]]:
        """Get installed DNF packages with license information (optimized)."""
        try:
            cmd = self._get_cmd()
            result = subprocess.run(
                [cmd, "list", "installed"],
                capture_output=True,
                text=True,
                check=True
            )

            # Parse package list
            package_list = []
            in_packages = False
            for line in result.stdout.strip().split('\n'):
                if "Installed Packages" in line:
                    in_packages = True
                    continue

                if in_packages and line.strip():
                    parts = line.split()
                    if len(parts) >= 2:
                        name = parts[0].split('.')[0]  # Remove architecture
                        version = parts[1]
                        package_list.append((name, version))

            # Get licenses for all packages concurrently
            packages = self._get_packages_with_licenses_concurrent(package_list, cmd)
            return packages

        except (subprocess.CalledProcessError, FileNotFoundError):
            return []

    def _get_packages_with_licenses_concurrent(self, package_list: List[Tuple[str, str]], cmd: str) -> List[Dict[str, any]]:
        """Get package information with licenses using concurrent processing."""
        packages = []

        # Separate cached and uncached packages
        cached_packages = []
        uncached_packages = []

        for package_name, version in package_list:
            cached_licenses = self.cache.get("dnf", package_name, version)
            if cached_licenses is not None:
                cached_packages.append({
                    "name": package_name,
                    "display_name": package_name,
                    "version": version,
                    "manager": "dnf",
                    "licenses": cached_licenses
                })
            else:
                uncached_packages.append((package_name, version))

        packages.extend(cached_packages)

        # Process uncached packages concurrently
        if uncached_packages:
            max_workers = min(16, len(uncached_packages))  # Limit concurrent processes

            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                # Submit all license fetch tasks
                future_to_package = {
                    executor.submit(self._get_dnf_license_single, pkg_name, version, cmd): (pkg_name, version)
                    for pkg_name, version in uncached_packages
                }

                # Collect results as they complete
                for future in as_completed(future_to_package):
                    package_name, version = future_to_package[future]
                    try:
                        licenses = future.result()

                        # Cache the result
                        self.cache.set("dnf", package_name, version, licenses)

                        packages.append({
                            "name": package_name,
                            "display_name": package_name,
                            "version": version,
                            "manager": "dnf",
                            "licenses": licenses
                        })
                    except Exception as e:
                        # If license fetch fails, use unknown
                        packages.append({
                            "name": package_name,
                            "display_name": package_name,
                            "version": version,
                            "manager": "dnf",
                            "licenses": ["unknown"]
                        })

        return packages

    def _get_dnf_license_single(self, package_name: str, version: str, cmd: str) -> List[str]:
